FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL;       // Consigna de velocidad deseada
    paroRapido : BOOL;  // Indica si se debe activar el paro rápido
    ciclo : TIME;       // Período de ejecución del bloque
END_VAR

VAR_OUTPUT
    CVvel : REAL;       // Consigna de velocidad actual
END_VAR

VAR
    lastCVvel : REAL;   // Valor de CVvel en la iteración anterior
    rampaSubida : REAL := 10.0;  // Pendiente de subida en puntos porcentuales por segundo
    rampaBajada : REAL := 20.0;  // Pendiente de bajada en puntos porcentuales por segundo
    rampaParoRapido : REAL := 40.0;  // Pendiente de paro rápido en puntos porcentuales por segundo
    tiempoCiclo : TIME;  // Tiempo transcurrido desde la última iteración
END_VAR

// Calcular el tiempo transcurrido desde la última iteración
tiempoCiclo := ciclo;

// Verificar si se debe activar el paro rápido
IF paroRapido THEN
    // Descender CVvel hacia 0.0 con una pendiente de 40.0 puntos porcentuales por segundo
    CVvel := MAX(0.0, lastCVvel - rampaParoRapido * REAL(tiempoCiclo / T#1s));
ELSE
    // Calcular la nueva CVvel según la consigna SPvel
    IF SPvel > lastCVvel THEN
        // Subida de velocidad
        CVvel := MIN(SPvel, lastCVvel + rampaSubida * REAL(tiempoCiclo / T#1s));
    ELSE
        // Bajada de velocidad
        CVvel := MAX(SPvel, lastCVvel - rampaBajada * REAL(tiempoCiclo / T#1s));
    END_IF;
END_IF;

// Actualizar el valor de lastCVvel para la próxima iteración
lastCVvel := CVvel;

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel     : REAL; (* Consigna de velocidad [%] *)
    paroRapido: BOOL; (* Paro rápido activo *)
    ciclo     : TIME; (* Período de ejecución del bloque *)
END_VAR

VAR_OUTPUT
    CVvel : REAL; (* Salida de velocidad con rampa [%] *)
END_VAR

VAR
    rSegundos   : REAL; (* Período en segundos *)
    rMaxSubida  : REAL; (* Incremento máximo por ciclo al subir *)
    rMaxBajada  : REAL; (* Decremento máximo por ciclo al bajar *)
    rMaxParada  : REAL; (* Decremento máximo por ciclo en paro rápido *)
    rError      : REAL; (* Diferencia entre SP y CV *)
END_VAR

(* ── Constantes de pendiente [puntos porcentuales / segundo] ── *)
CONST
    PENDIENTE_SUBIDA : REAL := 10.0;
    PENDIENTE_BAJADA : REAL := 20.0;
    PENDIENTE_PARO   : REAL := 40.0;
END_CONST

(* ── Conversión del período de ciclo a segundos ── *)
rSegundos := TIME_TO_REAL(ciclo) / 1000.0;

(* ── Incrementos máximos permitidos en este ciclo ── *)
rMaxSubida := PENDIENTE_SUBIDA * rSegundos;
rMaxBajada := PENDIENTE_BAJADA * rSegundos;
rMaxParada := PENDIENTE_PARO  * rSegundos;

IF paroRapido THEN
    (* ── Paro rápido: descender hacia 0.0 ignorando SPvel ── *)
    IF CVvel > 0.0 THEN
        CVvel := CVvel - rMaxParada;
        IF CVvel < 0.0 THEN
            CVvel := 0.0; (* Sin sobrepaso por debajo de 0 *)
        END_IF;
    ELSIF CVvel < 0.0 THEN
        (* Si por alguna razón CV fuera negativo, llevarlo a 0 *)
        CVvel := CVvel + rMaxParada;
        IF CVvel > 0.0 THEN
            CVvel := 0.0;
        END_IF;
    END_IF;
    (* Mientras paroRapido siga activo y CV = 0, permanece en 0 *)
ELSE
    (* ── Seguimiento normal de la consigna con rampa ── *)
    rError := SPvel - CVvel;

    IF rError > 0.0 THEN
        (* Subida: limitar el incremento a rMaxSubida *)
        CVvel := CVvel + rMaxSubida;
        IF CVvel > SPvel THEN
            CVvel := SPvel; (* Sin sobrepaso por arriba *)
        END_IF;

    ELSIF rError < 0.0 THEN
        (* Bajada: limitar el decremento a rMaxBajada *)
        CVvel := CVvel - rMaxBajada;
        IF CVvel < SPvel THEN
            CVvel := SPvel; (* Sin sobrepaso por abajo *)
        END_IF;

    (* Si rError = 0.0, CVvel ya es igual a SPvel; no se hace nada *)
    END_IF;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL; // Consigna de velocidad deseada
    paroRapido : BOOL; // Indicador de paro rápido
    ciclo : TIME; // Período de ejecución del bloque
END_VAR

VAR_OUTPUT
    CVvel : REAL; // Consigna de velocidad actualizada con rampa
END_VAR

VAR
    error : REAL; // Diferencia entre SPvel y CVvel
    deltaCVvel : REAL; // Cambio en CVvel durante el ciclo
    maxRampaSubida : REAL := 10.0; // Máxima rampa de subida en puntos porcentuales por segundo
    maxRampaBajada : REAL := 20.0; // Máxima rampa de bajada en puntos porcentuales por segundo
    maxRampaParoRapido : REAL := 40.0; // Máxima rampa de paro rápido en puntos porcentuales por segundo
    cicloSegundos : REAL; // Ciclo convertido a segundos
END_VAR

// Convertir el ciclo de tiempo a segundos
cicloSegundos := REAL(ciclo) / 1000.0;

// Calcular el error entre la consigna deseada y la actual
error := SPvel - CVvel;

// Determinar el cambio en CVvel según las condiciones
IF paroRapido THEN
    // Modo paro rápido: descender hacia 0 con una pendiente máxima
    deltaCVvel := -maxRampaParoRapido * cicloSegundos;
    IF CVvel + deltaCVvel < 0.0 THEN
        CVvel := 0.0;
    ELSE
        CVvel := CVvel + deltaCVvel;
    END_IF
ELSE
    // Modo normal: seguir la consigna con rampa
    IF error > 0 THEN
        // Subida de velocidad
        deltaCVvel := maxRampaSubida * cicloSegundos;
        IF CVvel + deltaCVvel > SPvel THEN
            CVvel := SPvel;
        ELSE
            CVvel := CVvel + deltaCVvel;
        END_IF
    ELSE
        // Bajada de velocidad
        deltaCVvel := -maxRampaBajada * cicloSegundos;
        IF CVvel + deltaCVvel < SPvel THEN
            CVvel := SPvel;
        ELSE
            CVvel := CVvel + deltaCVvel;
        END_IF
    END_IF
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel     : REAL;   (* Consigna de velocidad [%] *)
    paroRapido: BOOL;   (* Paro rápido activo *)
    ciclo     : TIME;   (* Período de ejecución del bloque *)
END_VAR

VAR_OUTPUT
    CVvel : REAL;       (* Salida de velocidad con rampa [%] *)
END_VAR

VAR
    rSegundos  : REAL;  (* Período de ciclo convertido a segundos *)
    rMaxSubida : REAL;  (* Incremento máximo permitido en un ciclo *)
    rMaxBajada : REAL;  (* Decremento máximo permitido en un ciclo *)
    rError     : REAL;  (* Diferencia entre consigna y salida actual *)
END_VAR

(* ── Constantes de pendiente [puntos porcentuales / segundo] ── *)
VAR CONSTANT
    PENDIENTE_SUBIDA    : REAL := 10.0;
    PENDIENTE_BAJADA    : REAL := 20.0;
    PENDIENTE_PARO_RAP  : REAL := 40.0;
END_VAR

(* ── Conversión del período de ciclo a segundos ── *)
rSegundos := TIME_TO_REAL(ciclo) / 1000.0;

IF paroRapido THEN
    (* ── Modo paro rápido: descender hacia 0.0 con pendiente rápida ── *)
    rMaxBajada := PENDIENTE_PARO_RAP * rSegundos;

    IF CVvel > 0.0 THEN
        CVvel := CVvel - rMaxBajada;
        (* Evitar sobrepaso por debajo de 0.0 *)
        IF CVvel < 0.0 THEN
            CVvel := 0.0;
        END_IF;
    ELSE
        (* Mantener en 0.0 mientras paroRapido siga activo *)
        CVvel := 0.0;
    END_IF;

ELSE
    (* ── Modo normal: seguir SPvel con pendientes limitadas ── *)
    rMaxSubida := PENDIENTE_SUBIDA * rSegundos;
    rMaxBajada := PENDIENTE_BAJADA * rSegundos;

    rError := SPvel - CVvel;

    IF rError > 0.0 THEN
        (* Consigna mayor que salida: subir con pendiente limitada *)
        IF rError > rMaxSubida THEN
            CVvel := CVvel + rMaxSubida;
        ELSE
            (* El paso restante es menor que el máximo: llegar exactamente *)
            CVvel := SPvel;
        END_IF;

    ELSIF rError < 0.0 THEN
        (* Consigna menor que salida: bajar con pendiente limitada *)
        IF (-rError) > rMaxBajada THEN
            CVvel := CVvel - rMaxBajada;
        ELSE
            CVvel := SPvel;
        END_IF;

    (* Si rError = 0.0, CVvel ya es igual a SPvel; no se hace nada *)
    END_IF;

END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL; // Consigna de velocidad deseada
    paroRapido : BOOL; // Indica si se debe activar el paro rápido
    ciclo : TIME; // Período de ejecución del bloque
END_VAR

VAR_OUTPUT
    CVvel : REAL; // Consigna de velocidad actual con rampa
END_VAR

VAR
    lastCVvel : REAL := 0.0; // Valor de CVvel en la última iteración
    rampaSubida : REAL := 10.0; // Pendiente de subida en puntos porcentuales por segundo
    rampaBajada : REAL := 20.0; // Pendiente de bajada en puntos porcentuales por segundo
    rampaParoRapido : REAL := 40.0; // Pendiente de paro rápido en puntos porcentuales por segundo
    tiempoCiclo : TIME := T#0s; // Tiempo transcurrido desde la última iteración
END_VAR

// Calcular el tiempo transcurrido desde la última iteración
tiempoCiclo := ciclo;

// Verificar si se debe activar el paro rápido
IF paroRapido THEN
    // Descender CVvel hacia 0.0 con la pendiente de paro rápido
    CVvel := lastCVvel - rampaParoRapido * REAL(tiempoCiclo / T#1s);
    // Asegurar que CVvel no sea menor que 0.0
    IF CVvel < 0.0 THEN
        CVvel := 0.0;
    END_IF
ELSE
    // Calcular la nueva CVvel con rampa
    IF SPvel > lastCVvel THEN
        // Subida de velocidad
        CVvel := lastCVvel + rampaSubida * REAL(tiempoCiclo / T#1s);
        // Asegurar que CVvel no supere el valor objetivo
        IF CVvel > SPvel THEN
            CVvel := SPvel;
        END_IF
    ELSE
        // Bajada de velocidad
        CVvel := lastCVvel - rampaBajada * REAL(tiempoCiclo / T#1s);
        // Asegurar que CVvel no sea menor que el valor objetivo
        IF CVvel < SPvel THEN
            CVvel := SPvel;
        END_IF
    END_IF
END_IF

// Actualizar el valor de lastCVvel para la próxima iteración
lastCVvel := CVvel;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL; (* Consigna de velocidad *)
    paroRapido : BOOL; (* Paro rápido activo *)
    ciclo : TIME; (* Ciclo de ejecución *)
END_VAR
VAR_OUTPUT
    CVvel : REAL; (* Condicional de velocidad *)
END_VAR
VAR
    error : REAL; (* Error entre SPvel y CVvel *)
    dt : TIME; (* Tiempo transcurrido desde la última ejecución *)
    dtSec : REAL; (* Tiempo transcurrido en segundos *)
    rampaSubida : REAL; (* Pendiente de subida *)
    rampaBajada : REAL; (* Pendiente de bajada *)
    rampaParoRapido : REAL; (* Pendiente de paro rápido *)
END_VAR

(* Inicialización de las rampas *)
rampaSubida := 10.0;
rampaBajada := 20.0;
rampaParoRapido := 40.0;

(* Cálculo del tiempo transcurrido en segundos *)
dt := ciclo;
dtSec := dt / T#1S;

(* Lógica de paro rápido *)
IF paroRapido THEN
    CVvel := MAX(0.0, CVvel - rampaParoRapido * dtSec);
ELSE
    (* Cálculo del error *)
    error := SPvel - CVvel;

    (* Ajuste de CVvel con rampa *)
    IF error > 0 THEN
        CVvel := MIN(CVvel + rampaSubida * dtSec, SPvel);
    ELSE
        CVvel := MAX(CVvel - rampaBajada * dtSec, SPvel);
    END_IF;
END_IF;

(* Evitar sobrepaso *)
IF CVvel > SPvel THEN
    CVvel := SPvel;
ELSIF CVvel < 0.0 THEN
    CVvel := 0.0;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL; (* Consigna de velocidad *)
    paroRapido : BOOL; (* Paro rápido activo *)
    ciclo : TIME; (* Ciclo de ejecución *)
END_VAR
VAR_OUTPUT
    CVvel : REAL; (* Consigna de velocidad variable *)
END_VAR
VAR
    error : REAL; (* Error entre SPvel y CVvel *)
    dt : TIME; (* Tiempo transcurrido desde la última iteración *)
    dt_sec : REAL; (* Tiempo transcurrido en segundos *)
    rampaSubida : REAL := 10.0; (* Pendiente de subida en puntos porcentuales por segundo *)
    rampaBajada : REAL := 20.0; (* Pendiente de bajada en puntos porcentuales por segundo *)
    rampaParoRapido : REAL := 40.0; (* Pendiente de paro rápido en puntos porcentuales por segundo *)
    lastTime : TIME; (* Tiempo de la última iteración *)
END_VAR

(* Calcula el tiempo transcurrido desde la última iteración *)
dt := ciclo;
dt_sec := dt / T#1S;

(* Actualiza CVvel según las condiciones *)
IF paroRapido THEN
    (* Paro rápido activo *)
    CVvel := CVvel - rampaParoRapido * dt_sec;
    IF CVvel < 0.0 THEN
        CVvel := 0.0;
    END_IF;
ELSE
    (* Paro rápido inactivo *)
    error := SPvel - CVvel;
    IF error > 0 THEN
        (* Subida *)
        CVvel := CVvel + rampaSubida * dt_sec;
        IF CVvel > SPvel THEN
            CVvel := SPvel;
        END_IF;
    ELSE
        (* Bajada *)
        CVvel := CVvel - rampaBajada * dt_sec;
        IF CVvel < SPvel THEN
            CVvel := SPvel;
        END_IF;
    END_IF;
END_IF;

(* Actualiza el tiempo de la última iteración *)
lastTime := lastTime + ciclo;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL;        // Setpoint de velocidad
    paroRapido : BOOL;   // Indicador de paro rápido
    ciclo : TIME;        // Período de ejecución del bloque
END_VAR
VAR_OUTPUT
    CVvel : REAL;        // Salida de velocidad controlada
END_VAR
VAR
    incremento : REAL;   // Incremento calculado para CVvel
    tiempoSegundos : REAL; // Tiempo de ciclo en segundos
END_VAR

// Convertir el tiempo de ciclo de TIME a REAL en segundos
tiempoSegundos := REAL_TO_REAL(TIME_TO_REAL(ciclo)) / 1000.0;

// Comprobar si el paro rápido está activo
IF paroRapido THEN
    // Calcular el decremento para paro rápido
    incremento := -40.0 * tiempoSegundos;
    // Ajustar CVvel asegurando que no sea menor que 0.0
    CVvel := CVvel + incremento;
    IF CVvel < 0.0 THEN
        CVvel := 0.0;
    END_IF
ELSE
    // Calcular la diferencia entre SPvel y CVvel
    incremento := SPvel - CVvel;

    // Determinar la dirección del ajuste
    IF incremento > 0.0 THEN
        // Ajuste al alza con pendiente máxima de 10.0
        incremento := 10.0 * tiempoSegundos;
        // Asegurar que CVvel no sobrepase SPvel
        IF CVvel + incremento > SPvel THEN
            CVvel := SPvel;
        ELSE
            CVvel := CVvel + incremento;
        END_IF
    ELSIF incremento < 0.0 THEN
        // Ajuste a la baja con pendiente máxima de 20.0
        incremento := -20.0 * tiempoSegundos;
        // Asegurar que CVvel no caiga por debajo de SPvel
        IF CVvel + incremento < SPvel THEN
            CVvel := SPvel;
        ELSE
            CVvel := CVvel + incremento;
        END_IF
    END_IF
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel     : REAL;   (* Consigna de velocidad [%] *)
    paroRapido: BOOL;   (* Paro rápido activo *)
    ciclo     : TIME;   (* Período de ejecución del bloque *)
END_VAR

VAR_OUTPUT
    CVvel : REAL;       (* Salida de velocidad con rampa [%] *)
END_VAR

VAR
    rPendiente  : REAL; (* Pendiente aplicada en este ciclo [puntos/%] *)
    rDelta      : REAL; (* Incremento/decremento máximo en este ciclo *)
    rSegundos   : REAL; (* Período de ciclo convertido a segundos *)
    rObjetivo   : REAL; (* Valor objetivo en este ciclo *)
END_VAR

(* ── Constantes de rampa [puntos porcentuales / segundo] ── *)
VAR CONSTANT
    C_RAMPA_SUBIDA  : REAL := 10.0;  (* Máx. subida  *)
    C_RAMPA_BAJADA  : REAL := 20.0;  (* Máx. bajada  *)
    C_RAMPA_PARO    : REAL := 40.0;  (* Paro rápido  *)
END_VAR

(* ── Conversión del período a segundos ── *)
rSegundos := TIME_TO_REAL(ciclo) / 1000.0;

IF paroRapido THEN
    (* ── Modo paro rápido: descender hacia 0.0 con rampa de 40 %/s ── *)
    rObjetivo := 0.0;

    IF CVvel > 0.0 THEN
        (* Calcular decremento máximo permitido en este ciclo *)
        rDelta := C_RAMPA_PARO * rSegundos;
        CVvel  := CVvel - rDelta;

        (* Evitar sobrepasar el objetivo (0.0) por debajo *)
        IF CVvel < 0.0 THEN
            CVvel := 0.0;
        END_IF;

    ELSIF CVvel < 0.0 THEN
        (* Si por alguna razón CVvel es negativo, subir hacia 0.0 *)
        rDelta := C_RAMPA_PARO * rSegundos;
        CVvel  := CVvel + rDelta;

        IF CVvel > 0.0 THEN
            CVvel := 0.0;
        END_IF;

    END_IF;
    (* CVvel = 0.0 exacto: no se modifica *)

ELSE
    (* ── Modo normal: seguir SPvel con rampa de subida/bajada ── *)
    rObjetivo := SPvel;

    IF CVvel < rObjetivo THEN
        (* Subida: pendiente limitada a C_RAMPA_SUBIDA *)
        rDelta := C_RAMPA_SUBIDA * rSegundos;
        CVvel  := CVvel + rDelta;

        (* Evitar sobrepasar el objetivo por arriba *)
        IF CVvel > rObjetivo THEN
            CVvel := rObjetivo;
        END_IF;

    ELSIF CVvel > rObjetivo THEN
        (* Bajada: pendiente limitada a C_RAMPA_BAJADA *)
        rDelta := C_RAMPA_BAJADA * rSegundos;
        CVvel  := CVvel - rDelta;

        (* Evitar sobrepasar el objetivo por abajo *)
        IF CVvel < rObjetivo THEN
            CVvel := rObjetivo;
        END_IF;

    END_IF;
    (* CVvel = rObjetivo exacto: no se modifica *)

END_IF;

FUNCTION_BLOCK FB_Rampa
VAR_INPUT
    SPvel : REAL;        // Setpoint de velocidad
    paroRapido : BOOL;   // Indicador de paro rápido
    ciclo : TIME;        // Período de ejecución del bloque
END_VAR

VAR_OUTPUT
    CVvel : REAL;        // Salida de consigna de velocidad
END_VAR

VAR
    incremento : REAL;   // Incremento calculado para CVvel
    tiempoSegundos : REAL; // Tiempo de ciclo en segundos
END_VAR

// Conversión del tiempo de ciclo de TIME a REAL en segundos
tiempoSegundos := REAL_TO_REAL(TIME_TO_REAL(ciclo)) / 1000.0;

// Comportamiento de paro rápido
IF paroRapido THEN
    incremento := -40.0 * tiempoSegundos;
    CVvel := CVvel + incremento;
    IF CVvel < 0.0 THEN
        CVvel := 0.0;
    END_IF
ELSE
    // Comportamiento normal de rampa
    IF SPvel > CVvel THEN
        incremento := 10.0 * tiempoSegundos;
        CVvel := CVvel + incremento;
        IF CVvel > SPvel THEN
            CVvel := SPvel;
        END_IF
    ELSIF SPvel < CVvel THEN
        incremento := -20.0 * tiempoSegundos;
        CVvel := CVvel + incremento;
        IF CVvel < SPvel THEN
            CVvel := SPvel;
        END_IF
    END_IF
END_IF
END_FUNCTION_BLOCK
